    input  wire [31:0] rs2_data_i,    // Data from RegFile rs2
    input  wire [31:0] imm_i,         // Extended immediate from imm_extend
    output reg  [31:0] b_o            // Operand B into ALU
);

    always @(*) begin
        case (alu_src_b_i)
            2'b00:   b_o = rs2_data_i;
            2'b01:   b_o = imm_i;
